import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第85章 两个小时","description":"","frontmatter":{},"headers":[],"relativePath":"第85章_两个小时.md","filePath":"第85章_两个小时.md"}'),_={name:"第85章_两个小时.md"};function r(n,p,s,u,c,i){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第85章-两个小时" tabindex="-1">第85章 两个小时 <a class="header-anchor" href="#第85章-两个小时" aria-label="Permalink to &quot;第85章 两个小时&quot;">​</a></h1><p>四月我们打了两个小时电话。</p><p>那一次什么都说了，除了那件正在坏的事。</p><p>打电话是她提的。</p><p>她说，我这里有个事想跟你讲，打字讲不完。</p><p>我说，你说。</p><p>她说，打电话吧。</p><p>我说，你那边现在几点。</p><p>她说，晚上七点。</p><p>我说，你那边的话你室友在吗。</p><p>她说，不在，她去自习。</p><p>我说，那你到走廊。</p><p>她说，我在阳台。</p><p>我说，阳台冷。</p><p>她说，我们那边二十二。</p><p>我说，那你披一件。</p><p>她说，你话真多。</p><p>那天我们讲了两个小时十四分钟。</p><p>我这边是凌晨。</p><p>我躲在被子里，手机贴着耳朵，我把音量调到最低那一格。</p><p>我们讲了什么呢。</p><p>我全部记得，我把它按顺序列一遍：</p><p>她讲了她那个展要撤了，撤下来的画她姨要拿去挂她们家客厅。</p><p>她讲了她那个房东把暖气修好了，修好以后她那边太热，她夜里开窗。</p><p>她讲了她最近在一个店里买到一种很便宜的冷冻豆子，一袋八毛。</p><p>她讲了她学会做一种饭，把米和水一起放，按一个键。</p><p>她讲了她的猫。</p><p>那只猫是她姨家楼下的，她每天喂，她给它起了一个名字，名字很难听。</p><p>她讲了她那天带那个猫去医院，医院收费一百二，她在门口站着算了一分钟。</p><p>她讲了她那个组的一个人把她的图发到群里，没有问她。</p><p>她讲了她把那张图撤下来了，撤完那个人给她发了三个感叹号。</p><p>她讲了她们那条街上开了一家新的奶茶店，招牌是方的。</p><p>她讲到这一句的时候，笑了一下。</p><p>她没有讲那家店的招牌换了。</p><p>她讲的是&quot;新开了一家&quot;。</p><p>我听懂了她为什么这样讲。</p><p>我如果听见&quot;新开了一家&quot;，我这边就会想&quot;那挺好，你以后不用喝旧的那家&quot;。</p><p>她不需要提旧的那家不在了。</p><p>我那天讲了什么。</p><p>我讲了我那个组，我讲了郑拓在谈恋爱，我讲了楼下的面馆换了老板。</p><p>我讲了我妈把我那件外套补了又穿回来了。</p><p>我讲了我三月没有去她那条巷子。</p><p>我讲到这里我停了。</p><p>她问，你为什么没去。</p><p>我说，我怕那边下雪，路滑。</p><p>她说，那你可以四月去。</p><p>我说，四月我在做展的事。</p><p>她说，哦。</p><p>她说，你今年好像特别忙。</p><p>我说，是。</p><p>那天我们两个小时里，只有一次差点碰到那件事。</p><p>就是她二月二十三号半夜接到的那个电话。</p><p>她讲了那个铁盒子，讲了账，讲了三百多笔。</p><p>她讲完以后，我这边沉默了几秒。</p><p>我那几秒里要讲的是一句：&quot;那天你为什么没回。&quot;</p><p>这句话我们两个都知道它在哪儿。</p><p>她说了一句话，把我这句挡回去了。</p><p>她说，那天晚上我妈跟我说&quot;你别回来，票贵&quot;。</p><p>我说，嗯。</p><p>她说，你猜我那天晚上有没有哭。</p><p>我说，没有。</p><p>她说，你怎么知道。</p><p>我说，因为你要哭了，你今天讲不到这一段。</p><p>她说，你今天讲话挺聪明的。</p><p>我说，我只是在你那边待得久。</p><p>她说，你没在我那边待过一天。</p><p>我说，我在你那些话里待得久。</p><p>那一句以后，她那边安静了很久。</p><p>我能听见她那边的风。</p><p>我能听见很远处有一辆车过去。</p><p>我能听见她自己的一次呼吸，比平时长。</p><p>她说，行了，不讲了。</p><p>我说，你不是有事讲不完。</p><p>她说，我本来是想跟你讲一件事。</p><p>我说，那你说。</p><p>她说，不说了。</p><p>我说，为什么。</p><p>她说，因为我在阳台上，我今天讲完这件事，我要进来睡，我要是讲了，我今天晚上睡不着。</p><p>她说，我明天要交图。</p><p>我说，那你不讲，你明天还是睡不着。</p><p>她说，不一样。</p><p>她说，我今天不讲，我是自己选的。</p><p>她说，我明天要是讲了，那是我今晚没忍住。</p><p>她说，我不喜欢我没忍住。</p><p>我说，那你哪天忍住了？</p><p>她说，每一天。</p><p>她说，我这一辈子就这一样本事。</p><p>两个小时十四分钟，最后是她那边有人回来了。</p><p>她压低声音说，我进来。</p><p>我说，好。</p><p>她说，你明天要上课。</p><p>我说，七点。</p><p>她说，那你现在就睡。</p><p>我说，你先挂。</p><p>她说，你先挂。</p><p>我说，你先挂，我听你挂。</p><p>她说，你这个人真的。</p><p>她说，那我挂了啊。</p><p>然后我听见那一下，很短的一声，线断了。</p><p>我拿手机贴在脸上，又贴了半分钟。</p><p>那半分钟里，那一边什么都没有，只有一点点电流的响声。</p><p>我那天夜里把这一场电话记进本子。</p><p>我记之前做了一件很无聊的事。</p><p>我去洗了脸，换了一件衣服。</p><p>我换那件衣服不是因为有人看。</p><p>我是觉得我要是对着她讲话，我穿的是那件睡了三天的，我自己过不去。</p><p>我记了十一件。</p><p>第二天我又看了一遍。</p><p>我发现我记错了两件。</p><p>第一，她说那个豆子是一袋八毛，我记成了十块。</p><p>第二，她说她那个展撤下来的画给她姨挂客厅，我记成了挂她自己家。</p><p>我坐在那儿看着这两处错。</p><p>这两处错很小。</p><p>小到如果她今天问我，我完全可以脸不红地讲错的那一个。</p><p>但是我知道这是什么。</p><p>我这一辈子存下来的东西，我以为它是镜子。</p><p>它不是。</p><p>它是一个每天都在删东西的硬盘。</p><p>我连她那天晚上讲的八毛钱的豆子都存不住，我凭什么存一个人。</p><p>那天我把那两处改了。</p><p>改完我在旁边写了一行。</p><p>我写：我抄的是她讲过的话，不是她在讲的时候。</p><p>我写：我存不住的不是她，我存不住的是那天晚上阳台上那二十度的风。</p><p>我记完才看清楚一件事。</p><p>十一个人里没有一件是重要的。</p><p>我们讲了两个多小时，讲的全是她那边的暖气、豆子、米、猫、八毛钱的袋子。</p><p>我们把那两个小时填得满满的。</p><p>填得那么满，是因为那里面有一件东西，我们两个都知道，我们两个都不敢放。</p><p>那天以后我又开始算。</p><p>我算出这场电话里，她主动讲了自己家的事，四次。</p><p>她主动讲了那个展，两次。</p><p>她一次也没讲她三月签不签那个活。</p><p>她生日那个晚上我知道她要签，她自己也知道我不会问。</p><p>我们两个把这件事放进了那十一件里。</p><p>那件事不占一个位置。</p><p>它占的是整个两小时。</p>',136)])])}const q=t(_,[["render",r]]);export{l as __pageData,q as default};
